import Foundation

/// Curated knowledge about where macOS, apps and developer tools keep their data.
public enum KnowledgeBase {
    // Shorthands keep the table below readable.
    private static func safe(_ s: String, _ cmd: String? = nil) -> CleanupAdvice { CleanupAdvice(.safe, s, command: cmd) }
    private static func review(_ s: String, _ cmd: String? = nil, regenerable: Bool = false) -> CleanupAdvice {
        CleanupAdvice(.review, s, command: cmd, regenerable: regenerable)
    }
    private static func caution(_ s: String, _ cmd: String? = nil) -> CleanupAdvice { CleanupAdvice(.caution, s, command: cmd) }
    private static func protected(_ s: String) -> CleanupAdvice { CleanupAdvice(.protected, s) }

    private static let appCache = "App cache. The app recreates it when needed, so removing it only costs a slightly slower first launch."

    public static let signatures: [Signature] = system + developer + packageManagers + projectArtifacts
        + virtualization + applicationData + fileTypes

